@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@500;600&display=swap');
:root{color-scheme:dark;--ink:#f3efe3;--muted:#a5a9b5;--gold:#e4c78c;--line:rgba(239,231,211,.2)}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101114;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}.game-shell{position:relative;width:100%;height:100%;min-height:320px;overflow:hidden;background:#151515;isolation:isolate}canvas{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;z-index:1;background:radial-gradient(ellipse at center,transparent 36%,rgba(5,6,9,.27) 100%),linear-gradient(180deg,rgba(8,9,13,.4),transparent 20%,transparent 72%,rgba(8,9,13,.48)}
.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:76px;padding:0 clamp(16px,4vw,54px);display:flex;align-items:center;gap:14px;background:linear-gradient(180deg,rgba(10,11,14,.7),transparent)}.topbar[hidden],.screen[hidden],.room-label[hidden],.crosshair[hidden],.objective[hidden],.interaction[hidden],.bottom-note[hidden]{display:none}.brand{font:500 10px 'DM Mono',monospace;letter-spacing:.18em;color:#e3ddcf}.brand-mark{color:var(--gold);font-size:20px;vertical-align:-2px;margin-right:8px}.progress{margin-left:auto;display:flex;align-items:baseline;gap:8px;font:12px 'DM Mono',monospace;color:#f0d7a4}.progress small{font-size:8px;letter-spacing:.14em;color:#99958d}.icon-button{width:34px;height:34px;border:1px solid var(--line);border-radius:50%;background:rgba(14,15,19,.4);cursor:pointer;color:#d4d1c9;font-size:15px}.icon-button:hover{background:rgba(228,199,140,.18);border-color:var(--gold)}
.screen{position:absolute;inset:0;z-index:5;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:24px;background:radial-gradient(ellipse at center,rgba(12,13,16,.48),rgba(9,10,13,.77) 78%);animation:appear .6s ease both}.screen[hidden]{display:none}@keyframes appear{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}.eyebrow{display:flex;align-items:center;gap:12px;font:9px 'DM Mono',monospace;letter-spacing:.2em;color:#d4c59f}.eyebrow span{width:22px;height:1px;background:rgba(228,199,140,.5)}h1,h2{font-family:'Playfair Display',Georgia,serif;font-weight:500;letter-spacing:-.045em;margin:19px 0 0}h1{font-size:clamp(54px,8.5vw,104px);line-height:.98;color:#f5f0e3}h1 span{color:var(--gold)}h2{font-size:clamp(43px,7vw,72px);line-height:1.04}.subtitle{font-size:clamp(15px,2vw,20px);font-family:'Playfair Display',Georgia,serif;font-style:italic;color:#d9d3c7;margin:17px 0 0}.intro{font-size:13px;line-height:1.9;color:#bbc0ca;margin:20px 0 0}.primary-button{margin-top:29px;padding:15px 23px;min-width:224px;border:1px solid rgba(228,199,140,.76);background:rgba(197,159,94,.12);font:10px 'DM Mono',monospace;letter-spacing:.15em;color:#f2dfb6;cursor:pointer;transition:background .2s,transform .2s}.primary-button span{font-size:16px;margin-left:15px}.primary-button:hover{background:rgba(197,159,94,.25);transform:translateY(-2px)}.control-hint,.small-hint{margin-top:25px;font:9px 'DM Mono',monospace;color:#9da3b0;letter-spacing:.06em}.control-hint kbd,.small-hint kbd,.interaction kbd{font:9px 'DM Mono',monospace;padding:4px 6px;border:1px solid rgba(230,232,237,.25);border-radius:3px;color:#d4d6dc;background:rgba(255,255,255,.04);margin:0 2px}.control-hint>span{padding:0 8px;color:#777}.mobile-hint{display:none;margin-top:12px;font:9px 'DM Mono',monospace;color:#969ba6}
.room-label{position:absolute;z-index:2;left:50%;top:19%;transform:translate(-50%,-6px);font:9px 'DM Mono',monospace;letter-spacing:.22em;color:rgba(246,231,201,.78);text-shadow:0 1px 14px #000;transition:opacity .5s}.objective{position:absolute;z-index:2;bottom:30px;left:50%;transform:translateX(-50%);white-space:nowrap;font:8px 'DM Mono',monospace;letter-spacing:.16em;color:rgba(242,235,216,.58);text-shadow:0 1px 6px #000}.objective span{color:#d8b979;padding:0 6px}.crosshair{position:absolute;z-index:2;top:50%;left:50%;width:13px;height:13px;transform:translate(-50%,-50%);opacity:.52}.crosshair i{position:absolute;display:block;background:#efe5cc}.crosshair i:first-child{width:1px;height:11px;left:6px;top:1px}.crosshair i:last-child{height:1px;width:11px;left:1px;top:6px}.interaction{position:absolute;z-index:3;left:50%;top:calc(50% + 28px);transform:translateX(-50%);display:flex;align-items:center;gap:8px;color:#f1ddad;font:8px 'DM Mono',monospace;letter-spacing:.17em;text-shadow:0 1px 8px #000}.interaction[hidden]{display:none}.interaction kbd{border-color:rgba(238,212,159,.6);color:#f1ddad}.toast{position:absolute;z-index:4;bottom:76px;left:50%;transform:translate(-50%,8px);padding:11px 16px;max-width:min(90vw,540px);text-align:center;background:rgba(13,14,16,.72);border:1px solid rgba(231,210,166,.25);color:#e9dfc9;font:10px 'DM Mono',monospace;letter-spacing:.06em;opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.bottom-note{position:absolute;z-index:2;bottom:27px;left:clamp(18px,4vw,54px);display:flex;align-items:center;gap:12px;font:8px 'DM Mono',monospace;letter-spacing:.18em;color:rgba(235,228,210,.43)}.note-line{width:35px;height:1px;background:rgba(228,199,140,.45)}
.touch-controls{position:absolute;z-index:3;left:0;right:0;bottom:max(15px,env(safe-area-inset-bottom));display:none;align-items:flex-end;justify-content:space-between;padding:0 20px;pointer-events:none}.touch-controls button{pointer-events:auto;border:1px solid rgba(241,232,207,.32);background:rgba(16,18,22,.55);backdrop-filter:blur(4px);color:rgba(244,235,213,.83);touch-action:none;user-select:none;-webkit-user-select:none}.move-pad{display:grid;grid-template-columns:repeat(3,43px);grid-template-rows:repeat(2,43px);gap:4px}.move-pad button{border-radius:50%;font-size:19px}.move-pad button[data-control=forward]{grid-column:2;grid-row:1}.move-pad button[data-control=left]{grid-column:1;grid-row:2}.move-pad button[data-control=back]{grid-column:2;grid-row:2}.move-pad button[data-control=right]{grid-column:3;grid-row:2}.listen-button{width:57px;height:57px;border-radius:50%;font:15px 'DM Mono',monospace!important;border-color:rgba(228,199,140,.45)!important;color:#f1dba8!important}.listen-button small{font:7px 'DM Mono',monospace;letter-spacing:.1em}.touch-controls button:active{background:rgba(228,199,140,.28)}
@media (pointer:coarse),(max-width:700px){.touch-controls{display:flex}.mobile-hint{display:block}.control-hint{display:none}.screen{padding-bottom:115px}.topbar{height:58px}.brand{font-size:8px;letter-spacing:.11em}.brand-mark{margin-right:5px}.objective{bottom:100px;font-size:7px;letter-spacing:.1em}.bottom-note{bottom:103px}.toast{bottom:165px}.room-label{top:15%}}
